$products = $service->products(); $prices = $service->recent('price_monitoring');
$pageTitle = 'Price Monitoring - Personnel'; $pageDescription = 'Real-time vegetable and staple price monitoring.'; $assetBase = 'assets'; $activePage = 'prices'; require_once __DIR__ . '/../frontend/components/header.php'; require_once __DIR__ . '/../frontend/components/personnel-nav.php';
?>
<main class="min-h-screen bg-surface-container-low"><section class="max-w-container-max mx-auto px-gutter-mobile lg:px-gutter-desktop py-space-xl"><p class="text-xs uppercase tracking-wider text-primary font-bold">Real-time market monitoring</p><h1 class="text-3xl font-extrabold mt-2">Price monitoring</h1><p class="text-sm text-on-surface-variant mt-2 mb-space-lg">Record current gulay and bugas prices by market and location.</p><?php if ($message): ?><div class="mb-4 rounded-lg border border-primary bg-primary/10 px-4 py-3 text-sm text-primary"><?= htmlspecialchars($message) ?></div><?php endif; ?><?php if ($error): ?><div class="mb-4 rounded-lg border border-error bg-error/10 px-4 py-3 text-sm text-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><div class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)] gap-space-lg"><form method="post" class="bg-surface-container-lowest border border-surface-container rounded-lg p-space-lg space-y-4"><input type="hidden" name="_csrf_token" value="<?= htmlspecialchars($csrf->token()) ?>"><h2 class="text-xl font-bold">Enter market price</h2><select name="product_id" required class="form-input-custom w-full rounded-lg p-3 text-sm border border-outline-variant"><option value="">Select product</option><?php foreach ($products as $product): ?><option value="<?= (int) $product['id'] ?>"><?= htmlspecialchars($product['name'] . ' (' . $product['unit'] . ')') ?></option><?php endforeach; ?></select><div class="grid grid-cols-2 gap-3"><input name="market_name" placeholder="Market" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="location" placeholder="Location" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><div class="grid grid-cols-2 gap-3"><input name="recorded_date" type="date" required value="<?= date('Y-m-d') ?>" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="source" placeholder="Source" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><div class="grid grid-cols-3 gap-3"><input name="minimum_price" type="number" min="0" step="0.01" placeholder="Min" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="maximum_price" type="number" min="0" step="0.01" placeholder="Max" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"><input name="average_price" type="number" min="0" step="0.01" required placeholder="Average" class="form-input-custom rounded-lg p-3 text-sm border border-outline-variant"></div><button class="rounded-lg bg-primary text-on-primary px-4 py-3 font-bold text-sm" type="submit">Save current price</button></form><div class="bg-surface-container-lowest border border-surface-container rounded-lg overflow-hidden"><div class="p-space-lg border-b border-surface-container flex items-center justify-between"><div><h2 class="text-xl font-bold">Latest price entries</h2><p class="text-xs text-on-surface-variant mt-1">Newest monitoring records first</p></div><a class="text-sm text-primary font-bold hover:underline" href="personnel-reports.php">Generate report</a></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-surface-container-low text-xs uppercase"><tr><th class="p-3">Date</th><th class="p-3">Product ID</th><th class="p-3">Average</th><th class="p-3">Market</th></tr></thead><tbody><?php foreach ($prices as $item): ?><tr class="border-t border-surface-container"><td class="p-3"><?= htmlspecialchars($item['recorded_date']) ?></td><td class="p-3"><?= (int) $item['product_id'] ?></td><td class="p-3 font-semibold">PHP <?= number_format((float) $item['average_price'], 2) ?></td><td class="p-3"><?= htmlspecialchars($item['market_name'] ?? '-') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section></main><?php require_once __DIR__ . '/../frontend/components/footer.php'; ?>
